import fs from "node:fs";
import path from "node:path";
import type { Browser, CDPSession, Page } from "@playwright/test";
import type { AppState } from "@/lib/state/app-state-types";
import type { StoreApi } from "zustand";
import { test, expect } from "../../fixtures/test-base";
import { prepareDenseComparisonFixture } from "../../helpers/dense-comparison-fixture";
import { prepareDenseStream } from "../../helpers/dense-canonical-stream";
import { verifyDenseThreadsFiles } from "../../helpers/dense-threads-fixture";
import { loadDenseCold } from "../../helpers/dense-cold-load";
import { captureDenseTraffic } from "../../helpers/dense-measurement";
import { dwell } from "../../helpers/causal-waits";
import { sha256File } from "../../helpers/dense-snapshot";

type CausalData = {
  stackTrace?: Array<{
    functionName?: string;
    url?: string;
    lineNumber?: number;
    columnNumber?: number;
  }>;
  sampleTraceId?: number;
};
type TraceEvent = {
  name: string;
  cat?: string;
  ph: string;
  pid: number;
  tid: number;
  ts: number;
  dur?: number;
  args?: { beginData?: CausalData; data?: CausalData };
};
type TraceComplete = {
  dataLossOccurred: boolean;
  stream?: string;
  traceFormat?: string;
  streamCompression?: string;
};
type CpuProfile = {
  startTime: number;
  endTime: number;
  nodes: unknown[];
  samples?: number[];
  timeDeltas?: number[];
};
const categories = [
  "toplevel",
  "devtools.timeline",
  "blink.user_timing",
  "disabled-by-default-devtools.timeline",
  "disabled-by-default-devtools.timeline.stack",
];
const directory = path.resolve(
  process.cwd(),
  "../../.kandev/diagnostics/dense-workbench-performance",
);

function writeJson(file: string, value: unknown) {
  fs.writeFileSync(file, JSON.stringify(value, null, 2), { flag: "wx" });
  const descriptor = fs.openSync(file, "r");
  fs.fsyncSync(descriptor);
  fs.closeSync(descriptor);
}

async function saveTrace(cdp: CDPSession, prefix: string) {
  const complete = new Promise<TraceComplete>((resolve) =>
    cdp.once("Tracing.tracingComplete", resolve),
  );
  await cdp.send("Tracing.end");
  const result = await complete;
  writeJson(prefix + ".trace-complete.json", result);
  expect(result.stream).toBeTruthy();
  const file = prefix + ".trace.json";
  const descriptor = fs.openSync(file, "wx");
  try {
    let eof = false;
    while (!eof) {
      const chunk = await cdp.send("IO.read", { handle: result.stream!, size: 1_048_576 });
      fs.writeSync(descriptor, Buffer.from(chunk.data, chunk.base64Encoded ? "base64" : "utf8"));
      eof = chunk.eof;
    }
    fs.fsyncSync(descriptor);
  } finally {
    fs.closeSync(descriptor);
    await cdp.send("IO.close", { handle: result.stream! });
  }
  expect(result.dataLossOccurred).toBe(false);
  expect(result.traceFormat).toBe("json");
  expect(result.streamCompression).toBe("none");
  const parsed = JSON.parse(fs.readFileSync(file, "utf8")) as { traceEvents: TraceEvent[] };
  expect(parsed.traceEvents.length).toBeGreaterThan(0);
  return { file, events: parsed.traceEvents, complete: result };
}

function markerWindow(events: TraceEvent[], names: { start: string; end: string }) {
  const start = events.filter((event) => event.name === names.start);
  const end = events.filter((event) => event.name === names.end);
  expect(start).toHaveLength(1);
  expect(end).toHaveLength(1);
  expect(start[0].pid).toBe(end[0].pid);
  expect(start[0].tid).toBe(end[0].tid);
  expect(end[0].ts).toBeGreaterThan(start[0].ts);
  return {
    pid: start[0].pid,
    tid: start[0].tid,
    startUs: start[0].ts,
    endUs: end[0].ts,
    elapsedMs: (end[0].ts - start[0].ts) / 1000,
    names,
  };
}

async function profileWindow(page: Page, prefix: string, stimulus: () => Promise<void>) {
  const cdp = await page.context().newCDPSession(page);
  const available = await cdp.send("Tracing.getCategories");
  writeJson(prefix + ".categories.json", available);
  expect(categories.every((category) => available.categories.includes(category))).toBe(true);
  const frame = await cdp.send("Page.getFrameTree");
  await cdp.send("Profiler.enable");
  await cdp.send("Profiler.start");
  const names = { start: path.basename(prefix) + ":start", end: path.basename(prefix) + ":end" };
  let tracing = false;
  let profile: CpuProfile | undefined;
  let trace: Awaited<ReturnType<typeof saveTrace>> | undefined;
  try {
    await cdp.send("Tracing.start", {
      traceConfig: {
        includedCategories: categories,
        recordMode: "recordUntilFull",
        traceBufferSizeInKb: 262_144,
      },
      transferMode: "ReturnAsStream",
      streamFormat: "json",
      streamCompression: "none",
    });
    tracing = true;
    await page.evaluate((name) => performance.mark(name), names.start);
    await stimulus();
    await page.evaluate((name) => performance.mark(name), names.end);
  } finally {
    const stopped = await cdp.send("Profiler.stop");
    profile = stopped.profile as CpuProfile;
    writeJson(prefix + ".cpuprofile", profile);
    if (tracing) trace = await saveTrace(cdp, prefix);
    await cdp.detach();
  }
  expect(trace).toBeDefined();
  const window = markerWindow(trace!.events, names);
  expect(profile.startTime).toBeLessThanOrEqual(window.startUs);
  expect(profile.endTime).toBeGreaterThanOrEqual(window.endUs);
  expect(profile.samples?.length).toBeGreaterThan(0);
  expect(profile.samples?.length).toBe(profile.timeDeltas?.length);
  const causalStacks = trace!.events
    .filter(
      (event) =>
        ["Layout", "UpdateLayoutTree"].includes(event.name) &&
        event.pid === window.pid &&
        event.tid === window.tid &&
        event.ts >= window.startUs &&
        event.ts < window.endUs,
    )
    .map((event) => ({ name: event.name, data: event.args?.beginData ?? event.args?.data }))
    .filter((event) => event.data?.stackTrace?.length);
  return {
    causalStacks,
    prefix,
    frame: frame.frameTree.frame,
    window,
    categories,
    trace: { path: trace!.file, sha256: sha256File(trace!.file), events: trace!.events.length },
    profile: {
      path: prefix + ".cpuprofile",
      sha256: sha256File(prefix + ".cpuprofile"),
      startTime: profile.startTime,
      endTime: profile.endTime,
      samples: profile.samples?.length,
      nodes: profile.nodes.length,
    },
    observedEvents: [
      ...new Set(
        trace!.events
          .filter((event) => event.pid === window.pid && event.tid === window.tid)
          .map((event) => event.name),
      ),
    ].sort(),
  };
}

async function calibrate(browser: Browser, prefix: string) {
  const context = await browser.newContext();
  const page = await context.newPage();
  const code =
    'window.forcedLayoutPositive = function forcedLayoutPositive(width) {\n  const probe = document.getElementById("probe");\n  probe.style.width = width + "px";\n  return probe.getBoundingClientRect().width;\n};\nwindow.forcedLayoutNegative = function forcedLayoutNegative(width) {\n  const probe = document.getElementById("probe");\n  probe.style.width = width + "px";\n  return probe.textContent;\n};\n//# sourceURL=kandev-forced-layout-calibration.js\n';
  try {
    await page.setContent('<div id="probe" style="width:40px;height:40px">trace</div>');
    await page.addScriptTag({ content: code });
    const captures = [];
    for (const mode of ["positive", "negative"] as const) {
      const capture = await profileWindow(page, prefix + "." + mode, () =>
        page.evaluate(async (selected) => {
          const api = window as Window & {
            forcedLayoutPositive: (width: number) => number;
            forcedLayoutNegative: (width: number) => string;
          };
          for (let frame = 0; frame < 12; frame++) {
            await new Promise<void>((resolve) => requestAnimationFrame(() => resolve()));
            if (selected === "positive") api.forcedLayoutPositive(40 + frame);
            else api.forcedLayoutNegative(80 + frame);
          }
        }, mode),
      );
      const stacks = capture.causalStacks.flatMap((event) => event.data?.stackTrace ?? []);
      const matches = stacks.filter((frame) => frame.url === "kandev-forced-layout-calibration.js");
      if (mode === "positive") {
        expect(matches.length).toBeGreaterThan(0);
        expect(matches.some((frame) => frame.functionName === "forcedLayoutPositive")).toBe(true);
      } else expect(matches).toEqual([]);
      captures.push({ mode, ...capture });
    }
    return { sourceCode: code, captures };
  } finally {
    await context.close();
  }
}

async function makeDenseContext(browser: Browser, url: string, port: number) {
  const context = await browser.newContext({
    baseURL: url,
    viewport: { width: 1470, height: 956 },
    deviceScaleFactor: 2,
    locale: "en-US",
  });
  const page = await context.newPage();
  await page.addInitScript((apiPort) => {
    localStorage.setItem("kandev.onboarding.completed", "true");
    window.__KANDEV_API_PORT = apiPort;
    (window as unknown as { __KANDEV_E2E_EXPOSE_STORE__: boolean }).__KANDEV_E2E_EXPOSE_STORE__ =
      true;
  }, String(port));
  return { context, page };
}

async function loadedHistory(page: Page, sessionIds: string[]) {
  return page.evaluate((ids) => {
    const store = (window as unknown as { __KANDEV_E2E_STORE__: StoreApi<AppState> })
      .__KANDEV_E2E_STORE__;
    return ids.map((sessionId) => ({
      sessionId,
      messages: store.getState().messages.bySession[sessionId]?.length ?? 0,
    }));
  }, sessionIds);
}

type PreparedFixture = Awaited<ReturnType<typeof prepareDenseComparisonFixture>>;
type ProbeMode = "no-selection" | "focused-composer";

async function selectionState(page: Page) {
  return page.evaluate(() => {
    const selection = window.getSelection();
    return {
      hasFocus: document.hasFocus(),
      rangeCount: selection?.rangeCount ?? 0,
      collapsed: selection?.isCollapsed ?? true,
      activeElementTag: document.activeElement?.tagName,
      activeElementTestId: document.activeElement?.getAttribute("data-testid"),
    };
  });
}

async function runCase(options: {
  mode: ProbeMode;
  row: Record<string, unknown>;
  browser: Browser;
  backend: Parameters<typeof prepareDenseComparisonFixture>[2];
  api: Parameters<typeof prepareDenseComparisonFixture>[0];
  prepared: PreparedFixture;
  prefix: string;
  checkpoint: () => void;
}) {
  const { mode, row, browser, backend, api, prepared, prefix, checkpoint } = options;
  let stream: Awaited<ReturnType<typeof prepareDenseStream>> | undefined;
  let context: Awaited<ReturnType<typeof makeDenseContext>>["context"] | undefined;
  try {
    const database = path.join(backend.tmpDir, `forced-layout-${mode}.db`);
    fs.copyFileSync(prepared.snapshot, database);
    expect(sha256File(database)).toBe(prepared.provenance?.databaseSha256);
    await backend.restart(
      {
        KANDEV_DATABASE_PATH: database,
        KANDEV_HOME_DIR: path.join(backend.tmpDir, `forced-layout-${mode}-home`),
        KANDEV_WEB_DIST_DIR: path.resolve(process.cwd(), "dist"),
        KANDEV_LOG_LEVEL: "warn",
        ...prepared.restartEnv,
      },
      path.resolve(process.cwd(), "../backend/bin/kandev"),
    );
    row.filesBefore = await verifyDenseThreadsFiles(api, prepared.backend, prepared.fixture);
    const threads = prepared.fixture.threads.slice(0, 6);
    stream = await prepareDenseStream(
      api,
      prepared.seed,
      prepared.backend,
      threads,
      prepared.sampleNamespace + "forced-layout-" + mode,
    );
    const target = await makeDenseContext(browser, backend.frontendUrl, backend.port);
    context = target.context;
    const { page } = target;
    row.cold = await loadDenseCold({
      page,
      workspaceId: prepared.seed.workspaceId,
      threads,
      warmup: stream.warmup,
      traffic: captureDenseTraffic(page),
    });
    const sessionIds = threads.map((thread) => thread.sessionId);
    row.initialLoadedHistory = await loadedHistory(page, sessionIds);
    expect(row.initialLoadedHistory).toEqual(
      sessionIds.map((sessionId) => ({ sessionId, messages: 100 })),
    );
    if (mode === "focused-composer") {
      const tile = page.getByTestId(`thread-column-${threads[0].taskId}`);
      const editor = tile.locator('.tiptap.ProseMirror[contenteditable="true"]');
      await tile.hover();
      await editor.click();
      await expect(editor).toBeFocused();
    } else {
      await page.evaluate(() => {
        (document.activeElement as HTMLElement | null)?.blur();
        window.getSelection()?.removeAllRanges();
      });
    }
    row.selectionBefore = await selectionState(page);
    if (mode === "no-selection")
      expect((row.selectionBefore as { rangeCount: number }).rangeCount).toBe(0);
    else expect((row.selectionBefore as { rangeCount: number }).rangeCount).toBe(1);
    checkpoint();
    const activeStream = stream;
    row.capture = await profileWindow(page, prefix + "." + mode, async () => {
      activeStream.release();
      await dwell(
        page,
        3_000,
        "clock-separation",
        "record three seconds of native forced layout call sites within the fixed ten-second quiet stream; diagnostic only",
      );
    });
    checkpoint();
    await stream.waitForVisible(page);
    await stream.verify();
    row.selectionAfter = await selectionState(page);
    row.scheduledUpdates = stream.scheduledUpdates;
    row.verificationErrors = stream.verificationErrors;
    row.finalLoadedHistory = await loadedHistory(page, sessionIds);
    expect(row.finalLoadedHistory).toEqual(row.initialLoadedHistory);
    row.filesAfter = await verifyDenseThreadsFiles(api, prepared.backend, prepared.fixture);
    expect(row.filesAfter).toEqual(row.filesBefore);
    row.allOrderedUpdatesVerified = true;
    row.status = "passed";
  } catch (error) {
    row.error = String(error);
    row.status = "failed";
  } finally {
    try {
      await stream?.finish();
    } catch (error) {
      row.finishError = String(error);
      row.status = "failed";
    }
    try {
      await context?.close();
    } catch (error) {
      row.closeError = String(error);
      row.status = "failed";
    }
    const log = path.join(backend.tmpDir, "backend-process.log");
    if (fs.existsSync(log)) fs.copyFileSync(log, prefix + "." + mode + ".backend.log");
    checkpoint();
  }
}

test("attributes forced layout with empty selection and a focused composer", async ({
  browser,
  testPage,
  apiClient: api,
  seedData: seed,
  backend,
}, info) => {
  test.setTimeout(600_000);
  fs.mkdirSync(directory, { recursive: true });
  const prefix = path.join(directory, `forced-layout-attribution-${Date.now()}`);
  const output = prefix + ".json";
  const report: Record<string, unknown> = {
    measurementKind: "forced-layout-attribution",
    assetsSha256: "b7c3fa9b16366da506d501e612df926f3cf3b73b1021401a4fa4fd49b673ebe4",
    limits:
      "Intrusive three-second traces within ten-second quiet streams. Focus is a diagnostic control. No native-v2 speed, field INP, M2 Air, battery or heap-leak claim. All ordered updates are verified after each observation window.",
    cases: [
      { mode: "no-selection", status: "pending" },
      { mode: "focused-composer", status: "pending" },
    ],
  };
  const checkpoint = () => fs.writeFileSync(output, JSON.stringify(report, null, 2));
  try {
    report.calibration = await calibrate(browser, prefix + ".calibration");
    checkpoint();
    const prepared = await prepareDenseComparisonFixture(api, seed, backend, testPage);
    report.fixture = prepared.fixture;
    report.fixtureReplay = prepared.provenance;
    checkpoint();
    for (const row of report.cases as Array<Record<string, unknown>>) {
      await runCase({
        mode: row.mode as ProbeMode,
        row,
        browser,
        backend,
        api,
        prepared,
        prefix,
        checkpoint,
      });
    }
    expect(
      (report.cases as Array<{ status: string }>).every((row) => row.status === "passed"),
    ).toBe(true);
  } catch (error) {
    report.error = String(error);
    throw error;
  } finally {
    checkpoint();
    const descriptor = fs.openSync(output, "r");
    fs.fsyncSync(descriptor);
    fs.closeSync(descriptor);
    await info.attach("forced-layout-attribution", {
      path: output,
      contentType: "application/json",
    });
  }
});

